  $$(".line-row").forEach(function(row){const quantity=Number($("[name=quantity]",row).value||0),price=Number($("[name=unit_price]",row).value||0),tax=Number($("[name=tax_rate]",row).value||0);total+=quantity*price*(1+tax/100);});
